    private static func genItem(
        _ id: String,
        _ categoryId: String,
        _ name: String,
        _ description: String,
        _ price: Int,
        _ tags: [DietaryTag]
    ) -> MenuItem {
        MenuItem(
            id: id,
            categoryId: categoryId,
            name: name,
            description: description,
            priceCents: price,
            tags: tags,
            imageURL: nil,
            isAvailable: true,
            customizations: []
        )
    }
